(function(){
  'use strict';
  function hexToBytes(s){
    var t=String(s||'').replace(/0x/gi,' ').replace(/[^0-9a-fA-F]/g,'');
    if(t.length%2) t=t.slice(0,-1);
    var o=new Uint8Array(t.length/2);
    for(var i=0;i<o.length;i++) o[i]=parseInt(t.substr(i*2,2),16);
    return o;
  }
  function toHex(b,sep){ var o=[]; for(var i=0;i<b.length;i++){var x=b[i].toString(16).toUpperCase(); o.push(x.length<2?'0'+x:x);} return o.join(sep===undefined?' ':sep); }
  function u16(b,p){ return (b[p]<<8)|b[p+1]; }

  var FUNCS={
    1:'读线圈 Read Coils', 2:'读离散输入 Read Discrete Inputs',
    3:'读保持寄存器 Read Holding Registers', 4:'读输入寄存器 Read Input Registers',
    5:'写单线圈 Write Single Coil', 6:'写单寄存器 Write Single Register',
    7:'读异常状态 Read Exception Status', 8:'诊断 Diagnostics',
    11:'取通信事件计数 Get Comm Event Counter', 12:'取通信事件日志 Get Comm Event Log',
    15:'写多线圈 Write Multiple Coils', 16:'写多寄存器 Write Multiple Registers',
    17:'报告从站 ID Report Server ID', 20:'读文件记录 Read File Record',
    21:'写文件记录 Write File Record', 22:'屏蔽写寄存器 Mask Write Register',
    23:'读写多寄存器 Read/Write Multiple Registers', 43:'封装接口 Encapsulated Interface'
  };
  var EXC={1:'非法功能码 ILLEGAL FUNCTION',2:'非法数据地址 ILLEGAL DATA ADDRESS',
           3:'非法数据值 ILLEGAL DATA VALUE',4:'从站设备故障 SERVER DEVICE FAILURE',
           5:'确认（长耗时）ACKNOWLEDGE',6:'从站忙 SERVER DEVICE BUSY',
           8:'存储奇偶校验错 MEMORY PARITY ERROR',10:'网关路径不可用 GATEWAY PATH UNAVAILABLE',
           11:'网关目标无响应 GATEWAY TARGET FAILED TO RESPOND'};

  function crc16(bytes){
    var crc=0xFFFF;
    for(var i=0;i<bytes.length;i++){
      crc ^= bytes[i];
      for(var j=0;j<8;j++){
        if(crc & 1) crc = (crc>>1) ^ 0xA001; else crc >>= 1;
      }
    }
    return crc & 0xFFFF;    // RTU 传输时低字节在前
  }
  function lrc(bytes){
    var s=0;
    for(var i=0;i<bytes.length;i++) s=(s+bytes[i])&255;
    return ((~s)+1)&255;
  }
  function bitsFromBytes(b, n){
    var out=[];
    for(var i=0;i<n;i++) out.push((b[i>>3]>>(i&7)) & 1);
    return out;
  }

  // ---- PDU 解析（功能码 + 数据），isResponse 决定字段含义 ----
  function decodePdu(fn, d, isResponse){
    var o={}, ex=(fn & 0x80)!==0, base=fn & 0x7F;
    if(ex){
      o['异常码']= d.length ? ((EXC[d[0]]||('未知 '+d[0]))+' (0x'+d[0].toString(16)+')') : '(缺失)';
      o['原功能码']= (FUNCS[base]||('未知 '+base))+' (0x'+base.toString(16)+')';
      return {fields:o, exception:true, code:d.length?d[0]:null};
    }
    if(!isResponse){
      if(fn===1||fn===2||fn===3||fn===4){
        if(d.length<4) return {fields:o, error:'请求数据不足 4 字节'};
        o['起始地址']= u16(d,0)+'  (0x'+u16(d,0).toString(16).toUpperCase()+')';
        o['数量']= u16(d,2);
        var q=u16(d,2), lim=(fn<=2)?2000:125;
        if(q<1||q>lim) o['⚠ 数量范围']= '规范要求 1..'+lim+'，当前 '+q;
      } else if(fn===5){
        if(d.length<4) return {fields:o, error:'请求数据不足 4 字节'};
        o['线圈地址']= u16(d,0);
        var val=u16(d,2);
        o['写入值']= val===0xFF00?'ON (0xFF00)':(val===0?'OFF (0x0000)':'非法 0x'+val.toString(16));
      } else if(fn===6){
        if(d.length<4) return {fields:o, error:'请求数据不足 4 字节'};
        o['寄存器地址']= u16(d,0);
        o['写入值']= u16(d,2)+'  (0x'+u16(d,2).toString(16).toUpperCase()+')';
      } else if(fn===15){
        if(d.length<5) return {fields:o, error:'请求数据不足'};
        o['起始地址']= u16(d,0); o['线圈数量']= u16(d,2); o['字节数']= d[4];
        var need=Math.ceil(u16(d,2)/8);
        if(d[4]!==need) o['⚠ 字节数']= '应为 '+need+'，实际 '+d[4];
        o['线圈值']= bitsFromBytes(d.subarray(5), Math.min(u16(d,2), (d.length-5)*8)).join('');
      } else if(fn===16){
        if(d.length<5) return {fields:o, error:'请求数据不足'};
        o['起始地址']= u16(d,0); o['寄存器数量']= u16(d,2); o['字节数']= d[4];
        if(d[4]!==u16(d,2)*2) o['⚠ 字节数']= '应为 '+(u16(d,2)*2)+'，实际 '+d[4];
        var regs=[];
        for(var i=5;i+1<d.length;i+=2) regs.push(u16(d,i));
        o['寄存器值']= regs.join(', ');
      } else if(fn===22){
        if(d.length<6) return {fields:o, error:'请求数据不足 6 字节'};
        o['寄存器地址']= u16(d,0); o['与掩码 AND']= '0x'+u16(d,2).toString(16).toUpperCase();
        o['或掩码 OR']= '0x'+u16(d,4).toString(16).toUpperCase();
      } else if(fn===23){
        if(d.length<9) return {fields:o, error:'请求数据不足'};
        o['读起始地址']= u16(d,0); o['读数量']= u16(d,2);
        o['写起始地址']= u16(d,4); o['写数量']= u16(d,6); o['写字节数']= d[8];
      } else if(fn===8){
        o['子功能']= u16(d,0); o['数据']= '0x'+u16(d,2).toString(16).toUpperCase();
      } else {
        o['原始数据']= toHex(d);
      }
      return {fields:o};
    }
    // 响应
    if(fn===1||fn===2){
      if(!d.length) return {fields:o, error:'响应缺少字节数'};
      o['字节数']= d[0];
      var bits=bitsFromBytes(d.subarray(1), (d.length-1)*8);
      o['位值(低位在前)']= bits.join('');
      if(d[0]!==d.length-1) o['⚠ 字节数']= '声明 '+d[0]+'，实际 '+(d.length-1);
    } else if(fn===3||fn===4){
      if(!d.length) return {fields:o, error:'响应缺少字节数'};
      o['字节数']= d[0];
      if(d[0]!==d.length-1) o['⚠ 字节数']= '声明 '+d[0]+'，实际 '+(d.length-1);
      var rs=[];
      for(var k=1;k+1<d.length;k+=2) rs.push(u16(d,k));
      o['寄存器值']= rs.join(', ');
      o.__regs=rs;
    } else if(fn===5||fn===6){
      if(d.length<4) return {fields:o, error:'响应数据不足 4 字节'};
      o['地址']= u16(d,0); o['回显值']= '0x'+u16(d,2).toString(16).toUpperCase();
    } else if(fn===15||fn===16){
      if(d.length<4) return {fields:o, error:'响应数据不足 4 字节'};
      o['起始地址']= u16(d,0); o['写入数量']= u16(d,2);
    } else {
      o['原始数据']= toHex(d);
    }
    return {fields:o};
  }

  function parse(input, mode, isResponse){
    var raw=String(input||'').trim();
    if(!raw) return {value:null, error:'输入为空'};
    mode = mode||'rtu';
    var b, notes=[];
    if(mode==='ascii'){
      var t=raw.replace(/\s/g,'');
      if(t.charAt(0)!==':') return {value:null, error:'ASCII 帧必须以 : 开头'};
      t=t.replace(/^:/,'').replace(/\r?\n?$/,'');
      if(t.length%2) return {value:null, error:'ASCII 帧十六进制位数为奇数'};
      b=hexToBytes(t);
      if(b.length<3) return {value:null, error:'ASCII 帧过短'};
      var gotLrc=b[b.length-1], body=b.subarray(0,b.length-1);
      var wantLrc=lrc(body);
      if(gotLrc!==wantLrc) notes.push('LRC 不匹配：报文 0x'+gotLrc.toString(16)+'，实算 0x'+wantLrc.toString(16));
      b=body;
    } else {
      b=hexToBytes(raw);
    }
    if(b.length<2) return {value:null, error:'帧过短（'+b.length+' 字节）'};

    var res={mode:mode, notes:notes, bytes:b.length};
    var pduStart, pduEnd=b.length;
    if(mode==='tcp'){
      if(b.length<8) return {value:null, error:'TCP 帧至少需要 7 字节 MBAP + 功能码'};
      res.mbap={ transaction:u16(b,0), protocol:u16(b,2), length:u16(b,4), unit:b[6] };
      if(res.mbap.protocol!==0) notes.push('协议标识应为 0（Modbus），当前 '+res.mbap.protocol);
      var expLen=b.length-6;
      if(res.mbap.length!==expLen) notes.push('MBAP 长度字段 '+res.mbap.length+' 与实际 '+expLen+' 不符');
      res.unit=b[6]; pduStart=7;
    } else if(mode==='ascii'){
      res.unit=b[0]; pduStart=1;
    } else {
      if(b.length<4) return {value:null, error:'RTU 帧至少需要 4 字节（地址+功能码+CRC）'};
      res.unit=b[0]; pduStart=1; pduEnd=b.length-2;
      var got=(b[b.length-1]<<8)|b[b.length-2];   // 低字节在前
      var want=crc16(b.subarray(0,b.length-2));
      res.crcGiven='0x'+got.toString(16).toUpperCase();
      res.crcCalc='0x'+want.toString(16).toUpperCase();
      res.crcOk = got===want;
      if(!res.crcOk) notes.push('CRC16 不匹配：报文 '+res.crcGiven+'，实算 '+res.crcCalc);
      if(res.unit===0) notes.push('从站地址 0 是广播地址，从站不应回复');
      if(res.unit>247) notes.push('从站地址 '+res.unit+' 超出 1..247 规范范围');
    }

    var fn=b[pduStart];
    res.func=fn & 0x7F;
    res.funcName = FUNCS[res.func] || ('未知功能码 '+res.func);
    res.isException = (fn & 0x80)!==0;
    res.direction = isResponse ? '响应' : '请求';
    var data=b.subarray(pduStart+1, pduEnd);
    var dec=decodePdu(fn, data, !!isResponse);
    res.fields=dec.fields;
    if(dec.error) notes.push(dec.error);
    if(dec.exception) res.exceptionCode=dec.code;
    res.pdu=toHex(b.subarray(pduStart, pduEnd));
    return {value:res, error:''};
  }

  // ---- 构建 ----
  function buildRtu(unit, fn, dataBytes){
    var arr=[unit & 255, fn & 255].concat(Array.prototype.slice.call(dataBytes||[]));
    var b=new Uint8Array(arr);
    var c=crc16(b);
    var out=new Uint8Array(b.length+2);
    out.set(b,0); out[b.length]=c & 255; out[b.length+1]=(c>>8)&255;
    return out;
  }
  function buildTcp(tid, unit, fn, dataBytes){
    var pdu=[fn & 255].concat(Array.prototype.slice.call(dataBytes||[]));
    var len=pdu.length+1;
    var out=new Uint8Array(7+pdu.length);
    out[0]=(tid>>8)&255; out[1]=tid&255; out[2]=0; out[3]=0;
    out[4]=(len>>8)&255; out[5]=len&255; out[6]=unit&255;
    out.set(pdu,7);
    return out;
  }
  function buildAscii(unit, fn, dataBytes){
    var arr=[unit & 255, fn & 255].concat(Array.prototype.slice.call(dataBytes||[]));
    var b=new Uint8Array(arr);
    return ':'+toHex(b,'')+ (function(){var x=lrc(b).toString(16).toUpperCase(); return x.length<2?'0'+x:x;})() + '\r\n';
  }
  function readRequest(unit, fn, addr, qty, mode, tid){
    var d=[(addr>>8)&255, addr&255, (qty>>8)&255, qty&255];
    if(mode==='tcp') return buildTcp(tid||1, unit, fn, d);
    if(mode==='ascii') return buildAscii(unit, fn, d);
    return buildRtu(unit, fn, d);
  }

  var API={parse:parse, crc16:crc16, lrc:lrc, buildRtu:buildRtu, buildTcp:buildTcp,
           buildAscii:buildAscii, readRequest:readRequest, hexToBytes:hexToBytes,
           toHex:toHex, FUNCS:FUNCS, EXC:EXC, bitsFromBytes:bitsFromBytes};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__ModbusForge__=API;
})();
